 interface Actions {void back();void select(String id);void changed(String title);void dismiss();}
 final AgentSettingsUi ui;final AgentRepository repository;final String thread;final Actions actions;final JSONObject protocol;final TextView notice;
 boolean open=true, pluginBusy;
 int pageRevision; String screen="home", activeGroup="all"; Runnable navigationBack;
 AgentNativeView(Context context,DrawerTheme theme,AgentRepository repository,String thread,Actions actions)throws Exception {
  super(context);setOrientation(VERTICAL);this.repository=repository;this.thread=thread;this.actions=actions;ui=new AgentSettingsUi(context,theme);
  try(InputStream in=context.getAssets().open("native/protocol.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);protocol=new JSONObject(out.toString("UTF-8"));}
  notice=ui.text("",12,false);notice.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){notice.setVisibility(s.length()==0?GONE:VISIBLE);}public void afterTextChanged(Editable e){}});home();
 }
 void reset(String title){pageRevision++;removeAllViews();screen=title;navigationBack=this::home;actions.changed(title);ui.add(this,notice,0);notice.setText("");notice.setVisibility(GONE);}
