  ui.listRow(common,"Conversation management","Search history, create branches, and archive",R.drawable.ic_chat_bubble_outline,()->group("threads"));
  ui.listRow(common,"Tasks and queue","Goals, budgets, and pending tasks",R.drawable.ic_task_alt,this::tasks);
  ui.add(this,common,0);
  LinearLayout tools=ui.listGroup();
