 void plugins(){reset("Plugins and marketplace");navigationBack=this::extensions;
  ui.add(this,ui.text("Plugins can provide skills and MCP tools. MCP processes currently have system-runtime privileges; enable only trusted sources.",13,false),0);
  LinearLayout list=ui.listGroup();ui.section(this,"Plugins",list);
  call("plugin/list",pluginListParams(),r->{JSONArray markets=r.optJSONArray("marketplaces");int count=0;
   if(markets!=null)for(int i=0;i<markets.length();i++){JSONObject market=markets.optJSONObject(i);if(market==null)continue;JSONArray items=market.optJSONArray("plugins");if(items==null)continue;
    for(int j=0;j<items.length();j++){JSONObject plugin=items.optJSONObject(j);if(plugin==null)continue;count++;
     JSONObject info=plugin.optJSONObject("interface");String title=info==null?"":info.optString("displayName","");if(title.isEmpty()||title.equals("null"))title=plugin.optString("name");
     String state=plugin.optBoolean("installed")?(plugin.optBoolean("enabled")?"Enabled":"Disabled"):"Available to install";
     String version=plugin.optString("localVersion","");if(version.equals("null"))version="";
     ui.listRow(list,title,state+(version.isEmpty()?"":" · "+version)+" · "+market.optString("name"),R.drawable.ic_home_apps,()->pluginDetail(market,plugin));
    }
   }
   if(count==0)ui.add(list,ui.text("This source has no plugins to display.",13,false),12);
   JSONArray errors=r.optJSONArray("marketplaceLoadErrors");if(errors!=null&&errors.length()>0)ui.add(this,ui.text("Some plugin sources could not be read. Check source configuration.",12,false),12);
   watchPlugins(pageRevision,r.toString(),null);
  });
 }
 void pluginDetail(JSONObject market,JSONObject plugin){reset("Plugin details");navigationBack=this::plugins;
  JSONObject info=plugin.optJSONObject("interface");String title=info==null?"":info.optString("displayName","");if(title.isEmpty()||title.equals("null"))title=plugin.optString("name");
  LinearLayout card=ui.card();ui.add(card,ui.text(title,18,true),0);
  String description=info==null?"":info.optString("shortDescription","");if(!description.isEmpty()&&!description.equals("null"))ui.add(card,ui.text(description,13,false),8);
  String version=plugin.optString("localVersion","");if(version.equals("null")||version.isEmpty())version="Unknown";
  ui.add(card,ui.text("Source: "+market.optString("name")+"\nVersion: "+version+"\nStatus: "+(plugin.optBoolean("installed")?(plugin.optBoolean("enabled")?"Enabled":"Disabled"):"Not installed"),12,false),12);ui.add(this,card,0);
  String id=plugin.optString("id"),name=plugin.optString("name"),path=market.optString("path");
  if(plugin.optBoolean("installed")){
   if(id.matches("[A-Za-z0-9_.@-]+"))ui.add(this,ui.button(plugin.optBoolean("enabled")?"Disable plugin":"Enable plugin",true,()->{JSONObject p=object("keyPath","plugins.\""+id+"\".enabled");try{p.put("mergeStrategy","upsert").put("value",!plugin.optBoolean("enabled"));}catch(Exception ignored){}pluginChange("config/value/write",p);}),16);
   ui.add(this,ui.button("Uninstall plugin",false,()->pluginConfirm("Uninstall",()->pluginChange("plugin/uninstall",object("pluginId",id)))),10);
   ui.add(this,ui.text("This interface does not yet support plugin updates or rollback.",12,false),14);
  }else if(!name.isEmpty()&&!path.isEmpty()&&!path.equals("null"))ui.add(this,ui.button("Install plugin",true,()->pluginConfirm("Install",()->{JSONObject p=object("pluginName",name);try{p.put("marketplacePath",path);}catch(Exception ignored){}pluginChange("plugin/install",p);})),16);
  if(!id.isEmpty())watchPlugins(pageRevision,plugin.toString(),id);
 }
 void pluginConfirm(String action,Runnable confirm){reset(action+" plugins");navigationBack=this::plugins;ui.add(this,ui.text(action.equals("Install")?"The plugin's MCP services will run with system-runtime privileges. Confirm that the source is trusted.":"This plugin's skills and tools will be unavailable after uninstalling.",14,false),0);ui.add(this,ui.button("Confirm "+action,true,confirm),16);ui.add(this,ui.button("Cancel",false,this::plugins),10);}
 void pluginChange(String method,JSONObject p){
  if(pluginBusy)return;pluginBusy=true;int revision=pageRevision;notice.setVisibility(VISIBLE);notice.setText("Updating plugin…");
  NativeClient.rpc(method,p,new NativeClient.Callback(){public void ready(JSONObject value){
   NativeClient.rpc("config/mcpServer/reload",new JSONObject(),new NativeClient.Callback(){public void ready(JSONObject ignored){pluginBusy=false;if(open&&revision==pageRevision)plugins();}public void failed(String message){pluginBusy=false;if(open&&revision==pageRevision){notice.setVisibility(VISIBLE);notice.setText("Plugin operation submitted, but MCP reload failed: "+message);}}});
  }public void failed(String message){pluginBusy=false;if(open&&revision==pageRevision){notice.setVisibility(VISIBLE);notice.setText(message);}}});
 }
 void toolCatalog(String server,JSONObject tools){reset("Extension tools");navigationBack=this::apps;EditText filter=ui.input("Search tools",InputType.TYPE_CLASS_TEXT);ui.add(this,filter,0);LinearLayout list=ui.listGroup();ui.add(this,list,8);
  Runnable render=()->{list.removeAllViews();if(tools==null)return;String query=filter.getText().toString().toLowerCase();ArrayList<String> names=new ArrayList<>();for(Iterator<String> it=tools.keys();it.hasNext();)names.add(it.next());Collections.sort(names);int shown=0;
   for(String name:names){JSONObject tool=tools.optJSONObject(name);String title=tool==null?name:tool.optString("title",name),description=tool==null?"":tool.optString("description");if(!(title+name+description).toLowerCase().contains(query))continue;shown++;
    ui.listRow(list,title,description,0,()->{reset(title);navigationBack=()->toolCatalog(server,tools);if(!description.isEmpty())ui.add(this,ui.text(description,12,false),0);EditText arguments=ui.input("Tool parameters JSON",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);arguments.setText("{}");ui.add(this,arguments,12);ui.add(this,ui.button("Call tool",true,()->{try{JSONObject p=params().put("serverName",server).put("toolName",name).put("arguments",new JSONObject(arguments.getText().toString()));call("mcpServer/tool/call",p,this::result);}catch(Exception e){notice.setVisibility(VISIBLE);notice.setText("Invalid tool parameter format");}}),12);});
   }if(shown==0)ui.add(list,ui.text("No matching tools",13,false),12);
  };render.run();filter.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(Editable e){}});
 }
